# J. N. Nicollet, Report Intended to Illustrate a Map of the Hydrographical Basin of the Upper Mississippi River,
# 26e Congrès, 2e session, Sénat, doc. 237, Washington, 1841 ; publié en 1843 (PDF du Drive de l'auteur, dossier
# NICOLLET_UPPER_MISSISSPPI ; texte lu en partie, 245 000 caractères). Préfixe NI41.
from commun import Corpus
NI = "Nicollet, Joseph-Nicolas (1841), Report Intended to Illustrate a Map of the Hydrographical Basin of the Upper Mississippi River, 26e Congrès, 2e session, Sénat, doc. 237"
C = Corpus('Recherches', 'NI41', NI, page_fmt='p. {}')
F = C.F
F('01', "Fort Pierre : Nicollet forme sa caravane, Provost chef des hommes (1er-3 juillet 1839)", 'exploration', '1839-07-01/1839-07-03', -100.385, 44.395, 'c', ['Joseph-Nicolas Nicollet', 'Etienne Provost', 'John C. Frémont', 'Pierre-Didier Papin', 'Louison Frenière', 'William Dixon'],
  "Monté de Saint-Louis par le vapeur de l'American Fur Company avec soixante ou soixante-dix Créoles, Canadiens et Métis, les « mangeurs de lard », Nicollet s'équipe au fort Pierre auprès de P. D. Papin. Des cinq hommes amenés de Saint-Louis, qui « en valaient certainement dix », l'un est Étienne Provost, « l'homme des montagnes », qu'il nomme chef de ses hommes ; il engage aussi comme guides et interprètes William Dixon, Louison Frenière et le fils de Baptiste Dorion, interprète du poste. Les voyageurs de l'Ouest, note-t-il, ne chantent jamais, à la différence de ceux des Grands Lacs, mais sont fidèles et courageux. Après une traversée périlleuse du Missouri les 1er et 2 juillet, la caravane de dix-neuf personnes, dix charrettes et trente chevaux monte le 3 sur le coteau du Missouri.",
  '42-44', "Nicollet dit aussi avoir été témoin des ravages de la variole sur le haut Missouri de 1836 à 1839. Point au fort Pierre.")
F('02', "Lac du Diable : le camp tout juste quitté des Métis de la rivière Rouge (29 juillet 1839)", 'evenement', '1839-07-28/1839-08-07~', -98.95, 48.05, 'c', ['Joseph-Nicolas Nicollet', 'John C. Frémont'],
  "Près du lac du Diable (Mini-wakan, « l'eau enchantée »), Nicollet découvre le camp que viennent de quitter les Métis de la rivière Rouge, aux traces profondes de leurs charrettes chargées. Il regrette de ne pas les avoir vus : descendants de Canadiens, d'Anglais et d'Écossais et de femmes sauteuses, cries, assiniboines et sioux, ils se disent « gens libres », sont six à huit cents, viennent deux fois l'an chasser le bison aux États-Unis, chaque famille avec sa charrette à bœufs, accompagnés de missionnaires, et sont devenus assez forts pour imposer la paix aux Sioux, Ricaras, Mandans et Gros-Ventres. Arrivée au lac le 29 juillet, la caravane y reste neuf jours ; les voyageurs nomment « Butte du Milieu » la seule hauteur d'où l'on embrasse le lac.",
  '48-50', "Point au lac du Diable (Dakota du Nord).")
# Ajouts du 20 nov. 2026 (relecture du même PDF, 245 000 caractères : campagnes de 1836, 1838 et 1839).
F('03', "Traverse des Sioux (Oiyuwega) : le passage des Sioux et le poste de traite (1838)", 'poste', '1838', -93.95, 44.354, 'c', ['Joseph-Nicolas Nicollet'],
  "À 116 milles de St. Peter's en remontant la rivière Saint-Pierre (Minnesota), la Traverse des Sioux, Oiyuwega pour les Sioux, est selon Nicollet appelée à devenir la position la plus importante de la vallée : bon débarcadère, sol excellent et boisé, force hydraulique d'un ruisseau voisin. Il s'y taille des canots de 32 pieds dans les cotonniers. Un poste de traite fait face au passage, et à un mille de là des cercles de pierres marquent un ancien camp dont les Sissetons, maîtres des lieux, n'ont gardé aucune tradition.",
  '12-13', "Point au site historique de Traverse des Sioux (St. Peter, Minnesota).")
F('04', "Lac qui Parle : la maison des Renville, seul refuge sur 700 milles (1838)", 'poste', '1838', -95.88, 45.02, 'a', ['Joseph Renville', 'Joseph-Nicolas Nicollet'],
  "Au Lac qui Parle réside la famille Renville, père et fils. Depuis des années, écrit Nicollet, leur maison est le seul refuge offert aux voyageurs entre St. Peter's et les postes britanniques, sur 700 milles ; il a lui-même profité de leur hospitalité, et leur grande influence sur les nations de la région maintient la paix et protège les voyageurs, ce qui mériterait la reconnaissance du gouvernement des États-Unis et de la Compagnie de la Baie d'Hudson. Il prévoit que l'endroit deviendra une étape du commerce naissant avec la colonie de la rivière Rouge. En 1838, c'est du Lac qui Parle que doit partir le renfort promis pour sa campagne de 1839.",
  '12-13, 41', "Point approximatif au fort Renville (parc d'État de Lac qui Parle).")
F('05', "La Grande Lisière de Bois (Great Oasis) : l'ancien poste de Joseph Laframboise (1838)", 'poste', '1838', -95.75, 44.05, 'h', ['Joseph Laframboise', 'Joseph-Nicolas Nicollet'],
  "Sur le plateau du Coteau des Prairies, le bosquet que les Sioux appellent Tchan-Haye-tanka et les voyageurs « la grande lisière de bois », entouré de lacs poissonneux, a longtemps été un poste de traite relevant de l'agence de St. Peter's. Joseph Laframboise, guide et interprète de Nicollet en 1838, y a vécu plusieurs années comme agent de l'American Fur Company ; le poste a été fermé depuis que les Wahpetons, les Sissetons et les Wahpekutes ont été décimés par leurs guerres avec les Sauks et les Renards et par la variole. Nicollet rapporte ailleurs que les traiteurs de la compagnie hivernent souvent aux sources de la Des Moines, et qu'une fois, faute de moyens de transport par terre, Laframboise fit construire un grand canot, y chargea ses pelleteries, s'embarqua sur la Tchanshetcha et gagna St. Peter's par la Watonwan et la Mankato.",
  '13-14, 24-25', "Position hypothétique : la Great Oasis est d'ordinaire située dans le comté de Murray (Minnesota) ; Nicollet ne donne pas de coordonnées. Le même texte nomme aussi les lacs Shetek, nom sauteux donné par les voyageurs.")
F('06', "La carrière de pierre à calumet : Nicollet la dégage et vaccine les Sioux (été 1838)", 'exploration', '1838-06/1838-07', -96.325, 44.013, 'c', ['Joseph-Nicolas Nicollet', 'Joseph Renville', 'Joseph Laframboise'],
  "À la carrière de pierre rouge, sur les terres des Sissetons, où les nations voisines viennent chaque année en pèlerinage, la caravane de Nicollet est accueillie par un violent orage qui manque de renverser le chariot de M. Renville. Le lendemain arrive un parti de Sioux qui les suivait depuis des jours ; après trois jours de purification rituelle, ils commencent à extraire la pierre. Pour l'atteindre, il faut faire sauter une couche de quartzite de quatre pieds et demi : Nicollet y met ses hommes, et en trois jours la carrière est dégagée. Il en profite pour faire ses observations astronomiques et vacciner les Autochtones qui se sont joints à son groupe.",
  '15-17', "Point au Pipestone National Monument (Minnesota). Le rapport ne date pas la visite au jour près.")
F('07', "Rivière aux Canots (Cannon River) : la cache des traiteurs", 'toponymie', '1700~/1763', -92.63, 44.6, 'a', ['Pierre-Charles Le Sueur'],
  "Au temps des Français, rapporte Nicollet, la rivière que l'on appelle maintenant Cannon River portait le nom de « rivière aux Canots », parce que les traiteurs avaient l'habitude d'y cacher leurs canots ; le nom anglais en est une déformation. Les Sioux l'appelaient déjà Inyan-bosndata quand Le Sueur remonta le Mississippi en 1700. Nicollet la nomme aussi rivière La Hontan.",
  '20-22', "Point à l'embouchure, près de Red Wing (Minnesota).")
F('08', "Les « côtes brûlées » du Missouri, entre Scalp Mountain et la Grande Courbe (1839)", 'toponymie', '1839', -99.3, 43.7, 'h', ['Joseph-Nicolas Nicollet'],
  "En remontant le Missouri en 1839, Nicollet longe sur 130 milles, de Scalp Mountain jusqu'au-delà de la Grande Courbe (Karmichigah), une zone noire que les voyageurs appellent « les côtes brûlées », collines visitées par des feux souterrains dont de nombreux traiteurs ont vu l'activité ; les parties les plus noires et stériles sont les plus récemment brûlées.",
  '39-41', "Position hypothétique, au milieu du tronçon décrit (Dakota du Sud).")
F('09', "Talle de Chênes (Otuhu oju), rivière Jacques : le rendez-vous d'un an (10 juillet 1839)", 'exploration', '1839-07-10', -98.45, 44.95, 'h', ['Joseph-Nicolas Nicollet', 'Etienne Provost', 'John C. Frémont'],
  "Parti du fort Pierre, Nicollet atteint le 10 juillet 1839 la rivière Jacques à un lieu célèbre que les Sioux appellent Otuhu oju, « là où poussent les chênes », et les Français la Talle de Chênes ; il le porte sur sa carte comme « Oakwood Settlement ». Il y avait fixé un an plus tôt, pour le 8 au 12 juillet, le rendez-vous du renfort qui devait venir du Lac qui Parle. Le renfort ne vint pas, mais Nicollet, qui avait entretenu l'espoir de ses hommes avec cette promesse, avait déjà pris le parti de s'en passer. Il estime l'endroit à 110 milles du fort Pierre, à 1 340 pieds d'altitude.",
  '41, 46-47', "Position hypothétique sur la rivière James (Dakota du Sud), à environ 110 milles du fort Pierre selon Nicollet.")
F('10', "Rivière Jacques : l'hiver de Louison Frenière, agent du fort Pierre (1836-1837)", 'commerce', '1836/1837', -98.6, 46.3, 'h', ['Louison Frenière'],
  "Le fort Pierre envoie parfois un agent troquer avec les bandes qui suivent la rivière Jacques. C'est à ce titre que Louison Frenière y passe l'hiver 1836-1837 : les bisons ne viennent pas, la variole se répand parmi toutes les nations de la région, il ne lui reste pour vivre que des racines déterrées sous la neige ; ses engagés meurent de faim, et au printemps sa maison est entourée de cadavres. Plus haut, la caravane de 1839 quitte la rivière à l'endroit que les voyageurs nomment « Butte aux Os », d'après un grand tas d'os d'animaux amassés par les Autochtones.",
  '47-48', "Position hypothétique sur la rivière James ; Nicollet ne situe pas la maison.")
F('11', "Coteau des Prairies : Louison Frenière peint de vermillon le cheval abandonné (1839)", 'evenement', '1839-08~', -97.1, 45.7, 'h', ['Louison Frenière', 'Joseph-Nicolas Nicollet', 'John C. Frémont'],
  "Sur le haut Coteau des Prairies, Nicollet prête son cheval blanc, compagnon de toute la campagne de 1839, à son guide métis Louison Frenière, qui accompagne Frémont dans l'exploration d'une série de lacs. Épuisé, le cheval doit être abandonné. Le lendemain, Frenière va le revoir et, avant de le laisser, lui peint la tête et le corps de vermillon pour le recommander aux génies du lieu et à tout Autochtone qui le trouverait.",
  '10-11', "Position hypothétique sur le haut Coteau des Prairies (nord-est du Dakota du Sud).")
F('12', "Lac des Chicots (Wamduskamde) : un nom des Métis de la rivière Rouge (1839)", 'toponymie', '1839-08~', -98.4, 47.89, 'a', ['Joseph-Nicolas Nicollet'],
  "Après le lac du Diable, la caravane atteint un lac salé en fer à cheval, de quinze à seize milles de tour, que les Sioux appellent Wamduskamde, le lac des Serpents, et que Nicollet croit être celui que les Métis de la rivière Rouge nomment « lac des Chicots ». Il se décharge dans la Cheyenne (Shayen oju) ; la troupe campe près d'un petit lac d'eau douce voisin.",
  '51-52', "Identifié d'ordinaire au lac Stump (Dakota du Nord), Wamduska en dakota ; l'identification au lac des Chicots est une supposition de Nicollet.")
F('13', "Lac Sangsue (Leech Lake) : Francis Brunet, le guide géant de la pointe à la Loutre (août 1836)", 'personnage', '1836-08', -94.4, 47.17, 'a', ['Francis Brunet', 'Joseph-Nicolas Nicollet', 'William T. Boutwell'],
  "En 1836, Nicollet passe une semaine au lac Sangsue, la tente plantée sur la pointe à la Loutre (Otter-tail Point), où réside son principal guide, Francis Brunet : six pieds trois pouces, un géant d'une grande force, plein de bonté et excellent géographe d'instinct. Les trois premiers jours, les Sauteux du lac, mécontents de la pauvreté de ses présents, menacent sa vie, et Brunet ose à peine prendre son parti. Ils l'appellent un « Français du vieux temps ». Le missionnaire William T. Boutwell, qui tente d'établir une mission chez les Pillagers du lac, traverse le lac le quatrième jour, malgré le vent, pour lui venir en aide. Nicollet estime la population du lac à un millier d'âmes.",
  '54-56, 63', "Point approximatif à la pointe Otter Tail du lac Leech (Minnesota).")
F('14', "Lac Itasca : Nicollet, Francis Brunet et le Sauteux Kegwedzissag aux sources du Mississippi (29 août 1836)", 'exploration', '1836-08-29', -95.207, 47.24, 'c', ['Joseph-Nicolas Nicollet', 'Francis Brunet'],
  "Parti du lac Sangsue dans un canot d'écorce avec trois compagnons, dont Francis Brunet et un Sauteux respecté, Kegwedzissag, qui chasse dans ce pays et le dit sien, Nicollet remonte par le lac Kabekonang jusqu'au lac Itasca. Le 29 août 1836, il explore le ruisseau principal qui s'y jette, large de 15 à 20 pieds à l'entrée, et le tient pour le véritable « Mississippi enfant », puisque ses sources sont les plus éloignées de l'embouchure.",
  '56-59', "Point au lac Itasca (Minnesota).")
fiches = C.fiches
